// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;

    function testFuzz_property(address actor, uint256 maxM, uint256 minM, uint256 rate) public {
        vm.assume(actor != address(0));
        minM = bound(minM, 0, 1e30);
        maxM = bound(maxM, minM, 1e40);
        rate = bound(rate, 0, 1e30);

        AC ac = new AC();
        c = new VaultAdapter();
        Proxy p = new Proxy(address(c));

        (bool initOk, ) = address(p).call(abi.encodeWithSignature("initialize(address)", address(ac)));
        assertTrue(initOk);

        ac.grantAccess(VaultAdapter.setLimits.selector, address(p), actor);

        vm.prank(actor);
        (bool ok, ) = address(p).call(
            abi.encodeWithSignature("setLimits(uint256,uint256,uint256)", maxM, minM, rate)
        );
        assertTrue(ok);
    }
}

contract AC {
    mapping(bytes4 => mapping(address => mapping(address => bool))) public allowed;

    function grantAccess(bytes4 s, address contractAddr, address a) external {
        allowed[s][contractAddr][a] = true;
    }

    function checkAccess(bytes4 s, address contractAddr, address caller) external view returns (bool) {
        return allowed[s][contractAddr][caller];
    }

    function initialize(address) external {}
}

contract Proxy {
    bytes32 constant IMPL_SLOT = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    constructor(address impl) {
        assembly {
            sstore(IMPL_SLOT, impl)
        }
    }

    fallback() external payable {
        address impl;
        assembly {
            impl := sload(IMPL_SLOT)
        }
        assembly {
            let ptr := mload(0x40)
            calldatacopy(ptr, 0, calldatasize())
            let result := delegatecall(gas(), impl, ptr, calldatasize(), 0, 0)
            returndatacopy(ptr, 0, returndatasize())
            switch result
            case 0 {
                revert(ptr, returndatasize())
            }
            default {
                return(ptr, returndatasize())
            }
        }
    }
}
